/* NOTE BENCH, ASSESS, FOR THE CONSOLE. Generated by
 * scripts/bench/build-console.mjs; edit the cases, the checks or the runner,
 * never this file.
 *
 * Open tools.nooutco.me/notes/assess/ logged in, keep the tab in front, and paste
 * the whole file into the console. It runs the 4 invented cases in
 * scripts/bench/cases/assess.json the way a user does: types each one, presses
 * Generate, answers the page's questions from the case's hidden details,
 * Sends, reads the note back and scores it. Between cases it presses Clear.
 *
 * It costs 4 drafts plus their question rounds, and sends only the
 * invented cases below. The results land on your clipboard. */
(() => {
  /* Chrome lends the console's copy() only while pasted code first runs, so
     it is taken before the first await. The report also stays on window. */
  const copyNow = typeof copy === 'function' ? copy : null;
  const CASES = [
    {
      "id": "assess-vbmapp-and-interview",
      "page": "/notes/assess/",
      "fields": {
        "Summary Notes": "ran VB-MAPP milestones levels 1 and 2 at home, 90 min. client did mands and tacts sections, mand at 6 items w full echoic, tact 8 items. listener 5 of the level 1 items. stopped level 2 at visual perceptual, client left table. barriers: prompt dependence and impaired mand. interviewed mom for 30 min about daily routine, sleep ok, eats 6 foods, tantrums mainly at bath time. scored level 1 today, level 2 partial. next visit finish level 2 and transition assessment."
      },
      "truth": [
        {
          "about": [
            "score",
            "milestone",
            "level 1",
            "total"
          ],
          "answer": "Level 1 total 11.5 of 15."
        },
        {
          "about": [
            "barrier",
            "prompt",
            "dependence"
          ],
          "answer": "Prompt dependence scored 2, impaired mand scored 3."
        },
        {
          "about": [
            "bath",
            "tantrum",
            "routine"
          ],
          "answer": "Mom says tantrums start when the water runs, about 5 minutes, 4 nights a week."
        }
      ],
      "expect": {
        "mentions": [
          "VB-MAPP",
          "Level 1",
          "prompt dependence",
          "bath",
          "Level 2"
        ],
        "forbid": [
          "was reinforced",
          "The Behavior Analyst",
          "Level 2 was completed",
          "transition assessment was completed"
        ],
        "picks": {
          "activities": [
            "Administration of assessment tool",
            "Caregiver/Guardian interview"
          ],
          "reporting": [
            "Assessment Scoring / Interpretation of results"
          ]
        },
        "notPicks": {
          "activities": [
            "Functional Analysis",
            "Review results with parent"
          ]
        }
      }
    },
    {
      "id": "assess-fba-observation-hypothesis",
      "page": "/notes/assess/",
      "fields": {
        "Summary Notes": "FBA visit at school, observed 2 hrs in class and at recess. ABC data on hitting, 7 episodes, 5 after teacher said clean up or line up, 2 at recess when peer took ball. most hits followed by teacher removing the demand. maybe escape, maybe tangible at recess, need more data before calling it. interviewed teacher 20 min, she says worse on mondays. did not do FA. next: indirect assessment w parents and 1 more observation."
      },
      "truth": [
        {
          "about": [
            "function",
            "hypothesis",
            "escape"
          ],
          "answer": "Not decided yet, escape is the leading guess for class, tangible for recess."
        },
        {
          "about": [
            "monday",
            "teacher",
            "setting"
          ],
          "answer": "Teacher thinks weekends at dad's house, not confirmed."
        }
      ],
      "expect": {
        "mentions": [
          "ABC",
          "escape",
          "tangible",
          "teacher",
          "observation"
        ],
        "forbid": [
          "was reinforced",
          "The Behavior Analyst",
          "function of the behavior is escape",
          "maintained by escape",
          "Functional Analysis was conducted"
        ],
        "picks": {
          "activities": [
            "Functional Behavior Assessment",
            "Client Observation"
          ]
        },
        "notPicks": {
          "activities": [
            "Functional Analysis",
            "Administration of assessment tool"
          ]
        }
      }
    },
    {
      "id": "assess-report-writing-no-client",
      "page": "/notes/assess/",
      "fields": {
        "Summary Notes": "report writing, no client contact. pulled prior treatment plan and last 6 months of data from rethink. read neuropsych eval from may and the speech eval. graphed manding and elopement trends, manding up steady, elopement flat since spring. drafted 4 new goals: 2 communication, 1 social, 1 behavior reduction for elopement. edited the background and history sections. still need to write the parent training goals before sending to clinical director."
      },
      "truth": [
        {
          "about": [
            "goals",
            "draft",
            "new"
          ],
          "answer": "Requesting help, 2 word mands, greeting peers, and elopement reduction."
        }
      ],
      "expect": {
        "mentions": [
          "neuropsych",
          "speech",
          "elopement",
          "parent training"
        ],
        "forbid": [
          "was reinforced",
          "The Behavior Analyst",
          "client was observed",
          "parent training goals were written"
        ],
        "picks": {
          "reporting": [
            "Medical Record Review",
            "Analysis of past data",
            "Treatment plan / goal development",
            "Report Review and Edits"
          ]
        },
        "notPicks": {
          "activities": [
            "Client Observation",
            "Administration of assessment tool",
            "Caregiver/Guardian interview"
          ]
        }
      }
    },
    {
      "id": "assess-results-review-with-parents",
      "page": "/notes/assess/",
      "fields": {
        "Summary Notes": "met w both parents 1 hr to go over the reassessment. showed VB-MAPP level 1 now complete, level 2 at about half, up from level 1 only at intake. walked through 5 proposed goals. dad asked why toilet training not in goals, explained we start once sitting tolerance is 2 min, they agreed. mom wants more help with bedtime, will add a parent training goal for bedtime routine. parents signed off on goals."
      },
      "truth": [
        {
          "about": [
            "bedtime",
            "parent training",
            "goal"
          ],
          "answer": "Goal will be a visual bedtime routine with mom, 3 steps to start."
        }
      ],
      "expect": {
        "mentions": [
          "toilet",
          "sitting tolerance",
          "bedtime",
          "signed off"
        ],
        "forbid": [
          "was reinforced",
          "The Behavior Analyst",
          "toilet training goal was added"
        ],
        "picks": {
          "activities": [
            "Review results with parent"
          ]
        },
        "notPicks": {
          "activities": [
            "Administration of assessment tool",
            "Client Observation"
          ]
        }
      }
    }
  ];

  // Each module keeps its own scope, as it has on disk.
  const checkParentDraft = (() => {
    /* What a right parent note must show, checked against a draft.
     *
     * Written 2026-10-03 from one production parent note that came out wrong, as
     * step 9 of the plan Kaleb approved. Each check is one of his rulings on that
     * note, so a failure names the ruling it breaks. The cases live in
     * tests/fixtures/parent-note-shape.json; parent-note-shape.spec.js proves
     * these checks catch the failures the real note had, and the same checks can
     * score a live draft (see that spec's header for how).
     *
     * `draft` is the parent tool's normalized output: individualsPresent,
     * supportActivities, caregiverResponse, progressStatus, summary, followup,
     * hints. */
    
    const QUESTION_LINE = /^\s*(clarify|specify|(confirm|verify|determine|check|ask|identify) (whether|if)|find out (whether|if))\b|\?\s*$/i;
    
    const lc = (s) => String(s || '').toLowerCase();
    const anyOf = (v) => [].concat(v);
    
    function checkParentDraft(c, draft) {
      const e = c.expect || {};
      const fails = [];
      const summary = String(draft.summary || '');
      const all = `${summary}\n${draft.followup || ''}`;
    
      for (const name of e.goalNames || []) {
        if (!lc(summary).includes(lc(name))) fails.push(`goal not named in the summary: "${name}"`);
      }
      for (const claim of e.forbidCountClaims || []) {
        if (lc(summary).includes(lc(claim))) fails.push(`a goal count the list does not support: "${claim}"`);
      }
      for (const p of e.forbidPhrases || []) {
        if (lc(all).includes(lc(p))) fails.push(`a phrase that must not appear: "${p}"`);
      }
      if (e.promptLevelWithCount) {
        // count may list several ways to write the same count ("2 of 3", "2
        // trials"); Kaleb's first live run wrote one the single form missed.
        const { count, level } = e.promptLevelWithCount;
        const forms = anyOf(count);
        const sentences = summary.split(/(?<=[.!?])\s+/);
        const withCount = sentences.filter((s) => forms.some((f) => lc(s).includes(lc(f))));
        if (!withCount.length) fails.push(`the trial count ("${forms.join('" or "')}") is missing`);
        else if (!withCount.some((s) => lc(s).includes(lc(level)))) fails.push(`the trial count is written without the prompt level ("${level}") beside it`);
      }
    
      const present = draft.individualsPresent || [];
      for (const who of e.individualsInclude || []) if (!present.includes(who)) fails.push(`Individuals Present is missing "${who}"`);
      for (const who of e.individualsExclude || []) if (present.includes(who)) fails.push(`Individuals Present lists "${who}", whom the notes place out of the session`);
    
      if (e.caregiverResponse && draft.caregiverResponse !== e.caregiverResponse) {
        fails.push(`Caregiver Response picked "${draft.caregiverResponse}", expected "${e.caregiverResponse}"`);
      }
      if (e.progressStatus && draft.progressStatus !== e.progressStatus) {
        fails.push(`Progress Status picked "${draft.progressStatus}", expected "${e.progressStatus}"`);
      }
    
      const items = String(draft.followup || '').split('\n').map((s) => s.trim()).filter(Boolean);
      if (e.followupItems) {
        const [lo, hi] = e.followupItems;
        if (items.length < lo || items.length > hi) fails.push(`Follow Up has ${items.length} item(s), expected ${lo} to ${hi}`);
      }
      for (const line of items) if (QUESTION_LINE.test(line)) fails.push(`Follow Up holds a question to the author: "${line}"`);
      // An entry may list alternatives: ["BT", "technician"] is met by either.
      for (const entry of e.followupMentions || []) {
        const words = anyOf(entry);
        if (!items.some((l) => words.some((w) => lc(l).includes(lc(w))))) fails.push(`no Follow Up item mentions "${words.join('" or "')}"`);
      }
      return fails;
    }
    return checkParentDraft;
  })();

  const checkNote = (() => {
    /* THE BENCH'S CHECKS, one set for every tool.
     *
     * Each check is one of Kaleb's rulings or one point of his BT Session Note
     * Resources guide, so a failure names the rule it breaks. A case's `expect`
     * says which apply:
     *
     *   mentions   phrases the note must carry (the intake's facts, as written)
     *   forbid     phrases it must not (an invented fact, a hollow line, "was
     *              reinforced", "responded well")
     *   picks      { group: [labels that must be ticked] }
     *   notPicks   { group: [labels that must not be] }
     *   single     { group: label } for a single-select
     *   noData     true for BT: no percentage or a/b count in a narrative, because
     *              ReThink already pulls the data in (his guide)
     *   tasksOnly  narrative keys that hold tasks, never a question to the author
     *
     * And on every note: no opaque token left, no em dash, no blank single-select.
     * The parent tool's own checks (scripts/lib/parent-shape-checks.mjs) run too
     * when the case carries `parentExpect`. */
    
    const lc = (s) => String(s || '').toLowerCase();
    const QUESTION = /^\s*(clarify|specify|(confirm|verify|determine|check|ask|identify) (whether|if)|find out (whether|if))\b|\?\s*$/i;
    
    /* The note as the parent checker reads it: narratives by key, picks by group,
       a single-select as its one label. */
    function flatDraft(note, singles = []) {
      const out = { ...note.text };
      for (const [group, on] of Object.entries(note.picks || {})) {
        out[group] = singles.includes(group) ? (on[0] || '') : on;
      }
      return out;
    }
    
    function checkNote(c, note) {
      const e = c.expect || {};
      const fails = [];
      const narratives = Object.values(note.text || {}).join('\n');
      const all = note.all || narratives;
    
      for (const m of e.mentions || []) if (!lc(all).includes(lc(m))) fails.push(`missing from the note: "${m}"`);
      for (const f of e.forbid || []) if (lc(all).includes(lc(f))) fails.push(`must not appear: "${f}"`);
      for (const [group, labels] of Object.entries(e.picks || {})) {
        const on = (note.picks || {})[group] || [];
        for (const l of labels) if (!on.includes(l)) fails.push(`${group} is missing "${l}"`);
      }
      for (const [group, labels] of Object.entries(e.notPicks || {})) {
        const on = (note.picks || {})[group] || [];
        for (const l of labels) if (on.includes(l)) fails.push(`${group} wrongly has "${l}"`);
      }
      for (const [group, label] of Object.entries(e.single || {})) {
        const on = (note.picks || {})[group] || [];
        if (on[0] !== label) fails.push(`${group} picked "${on[0] || '(blank)'}", expected "${label}"`);
      }
      if (e.noData) {
        const hit = narratives.match(/\b\d+\s*\/\s*\d+\b|\b\d+(?:\.\d+)?\s*%|\b\d+ (?:of|out of) \d+\b/);
        if (hit) fails.push(`repeats data ReThink already pulls in: "${hit[0]}"`);
      }
      for (const key of e.tasksOnly || []) {
        for (const line of String((note.text || {})[key] || '').split('\n')) {
          if (line.trim() && QUESTION.test(line)) fails.push(`${key} holds a question to the author: "${line.trim()}"`);
        }
      }
      if (/\[\[T\d+\]\]/.test(all)) fails.push('an opaque token was left in the note');
      if (/\u2014/.test(narratives)) fails.push('an em dash in a narrative');
      for (const group of e.singlesNeverBlank || []) {
        if (!((note.picks || {})[group] || [])[0]) fails.push(`${group} left blank`);
      }
      if (c.parentExpect) fails.push(...checkParentDraft({ expect: c.parentExpect }, flatDraft(note, ['caregiverResponse', 'progressStatus'])));
      return fails;
    }
    return checkNote;
  })();

  /* THE BENCH IN HIS CONSOLE. Kaleb, 2026-10-04 (bench access, B): no bench
   * login; he pastes the bench into the console of a tool page he is logged in
   * on, one tool per sitting, as with the parent live script.
   *
   * This is lib/drive.mjs done from inside the page: the same steps a user takes
   * (fill the case, Generate, answer the page's questions from the case's truth,
   * Send, read the note card back), with plain DOM calls in place of Playwright.
   * Between cases it presses the page's own Clear, which drops the inputs, the
   * note and the scrub ledger; the confirm that Clear asks is answered yes for
   * that one press.
   *
   * The site refuses to be framed (X-Frame-Options DENY), so a case cannot run in
   * an iframe; Clear is what makes several cases one sitting.
   *
   * Built into scripts/bench/console/<tool>.js by scripts/bench/build-console.mjs,
   * which inlines the cases and lib/checks.mjs. This file must stay free of
   * imports: it is stringified into that script. */
  async function benchInPage(CASES, checkNote, opts = {}) {
    const LIMIT = opts.timeoutMs || 180000;
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    const words = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
    const $ = (sel) => document.querySelector(sel);
    const $$ = (sel) => [...document.querySelectorAll(sel)];
    const shown = (el) => !!el && el.getClientRects().length > 0;
    const until = async (fn, what, ms = LIMIT) => {
      const end = Date.now() + ms;
      for (;;) {
        const v = fn();
        if (v) return v;
        if (Date.now() > end) throw new Error(`timed out waiting for ${what}`);
        await sleep(250);
      }
    };
  
    /* React keeps a field's value in state, so the value is set through the
       element's own setter and announced with an input event, as typing does. */
    const type = (el, text) => {
      const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
      Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, text);
      el.dispatchEvent(new Event('input', { bubbles: true }));
    };
    const enter = (el) => el.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true, cancelable: true }));
    const button = (re, root = document) => [...root.querySelectorAll('button')].find((b) => re.test(b.textContent.trim()) && shown(b));
  
    /* The page's in-flight calls, counted so the passes after the first draft
       (self-revision, corrections) can settle before the note is read. Put back
       when the run ends. */
    let inFlight = 0;
    const realFetch = window.fetch;
    window.fetch = function (...args) {
      inFlight += 1;
      return realFetch.apply(this, args).finally(() => { inFlight -= 1; });
    };
    const settle = async () => {
      const end = Date.now() + (opts.settleMs || 60000);
      let quiet = 0;
      while (Date.now() < end && quiet < 6) { quiet = inFlight ? 0 : quiet + 1; await sleep(250); }
    };
  
    const clear = async () => {
      const b = [...document.querySelectorAll('button')].find((x) => x.textContent.trim() === 'Clear' && shown(x));
      if (!b) return;
      const realConfirm = window.confirm;
      window.confirm = () => true;
      try { b.click(); } finally { window.confirm = realConfirm; }
      await until(() => !$('[data-testid="generated-note"]') && !$('[data-panel-question]'), 'the page to clear', 10000);
    };
  
    const fieldNamed = (label) => {
      const re = new RegExp(label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
      return $$('textarea, input').find((el) => {
        const name = el.getAttribute('aria-label') || (el.labels && el.labels[0] ? el.labels[0].textContent : '') || el.placeholder || '';
        return re.test(name) && shown(el);
      });
    };
  
    const fill = async (c) => {
      // A toggle is its label paragraph followed by a row of buttons.
      for (const [label, value] of Object.entries(c.toggles || {})) {
        const p = $$('p').find((x) => x.textContent.includes(label));
        const row = p && p.nextElementSibling;
        const b = row && [...row.querySelectorAll('button')].find((x) => x.textContent.trim() === value);
        if (!b) throw new Error(`no "${value}" button under "${label}"`);
        b.click();
      }
      for (const [field, value] of Object.entries(c.choices || {})) {
        const b = $(`[data-arrival-field="${field}"] [data-arrival="${value}"]`);
        if (!b) throw new Error(`no "${value}" choice for ${field}`);
        b.click();
      }
      for (const [label, text] of Object.entries(c.fields || {})) {
        const el = fieldNamed(label);
        if (!el) throw new Error(`no field named "${label}" on this page`);
        type(el, text);
      }
      await sleep(300);
    };
  
    const clearGates = async () => {
      await sleep(500);
      const ack = $('#notes-ack-go');
      if (shown(ack)) { const cb = $('#notes-ack-cb'); if (cb && !cb.checked) cb.click(); ack.click(); }
      const review = $('#notes-scrub-go');
      if (shown(review)) review.click();
    };
  
    // The truth entry whose words the question shares most, as drive.mjs does.
    const answerFor = (question, truth) => {
      const q = String(question || '').toLowerCase();
      let best = null, bestHits = 0;
      for (const t of truth || []) {
        const hits = (t.about || []).filter((k) => q.includes(String(k).toLowerCase())).length;
        if (hits > bestHits) { best = t; bestHits = hits; }
      }
      return best ? best.answer : null;
    };
  
    const openPanel = async () => {
      if (shown($('.revision-input'))) return;
      const fab = $('.revision-fab');
      if (shown(fab)) fab.click();
      await until(() => shown($('.revision-input')), 'the panel to open', 5000);
    };
  
    // Same reading as drive.mjs readNote: picks per group, text per narrative.
    const readNote = () => {
      const card = $('[data-testid="generated-note"]');
      const picks = {};
      card.querySelectorAll('[data-section-id]').forEach((sec) => {
        const on = [...sec.querySelectorAll('[data-option][data-on="1"]')].map((o) => o.getAttribute('data-option'));
        if (sec.querySelector('[data-option]')) picks[sec.getAttribute('data-section-id')] = on;
      });
      const text = {};
      card.querySelectorAll('[data-section-key]').forEach((sec) => {
        const key = sec.getAttribute('data-section-key');
        const single = sec.querySelector('[data-single-answer]');
        if (single) { picks[key] = [single.getAttribute('data-single-answer')]; return; }
        if (sec.querySelector('[data-section-id] [data-option]') || picks[key]) return;
        const ta = sec.querySelector('textarea');
        if (ta) text[key] = ta.value;
      });
      const fields = [...card.querySelectorAll('textarea, input:not([type]), input[type="text"]')].map((t) => t.value);
      return { picks, text, all: [card.innerText, ...fields].join('\n') };
    };
  
    const runCase = async (c) => {
      const started = Date.now();
      await clear();
      await fill(c);
      const go = button(/^(Generate|Regenerate)(?! Prompt)/);
      if (!go) throw new Error('no Generate button: log in first');
      go.click();
      await clearGates();
  
      const typed = { intake: Object.values(c.fields || {}).reduce((n, t) => n + words(t), 0), answers: 0 };
      const asked = [];
      const noteUp = () => shown($('[data-testid="generated-note"]'));
      await until(() => noteUp() || $('[data-panel-question]'), 'the first questions or the note');
  
      // Up to 3 rounds, the page's own cap.
      for (let round = 0; round < 3 && !noteUp(); round++) {
        if (!$('[data-panel-question]')) break;
        await openPanel();
        const loose = [];
        for (const el of $$('[data-panel-question]')) {
          const i = el.getAttribute('data-panel-question');
          const question = el.innerText.split('\n')[0];
          const answer = answerFor(question, c.truth);
          asked.push({ round: round + 1, question, answered: !!answer });
          if (!answer) continue;
          typed.answers += words(answer);
          const own = $(`[data-suggestion-own="${i}:own"]`);
          if (shown(own)) { type(own, answer); enter(own); } else loose.push(answer);
        }
        if (loose.length) type($('.revision-input'), loose.join(' '));
        // Send opens once enough is written, or when the page's minute runs out.
        const send = await until(() => { const b = $('.revision-send'); return b && !b.disabled && b; }, 'Send to open');
        send.click();
        const last = asked.length ? asked[asked.length - 1].question : '';
        await until(() => noteUp() || ($('[data-panel-question]') && $('[data-panel-question]').innerText.split('\n')[0] !== last), 'the next round or the note').catch(() => {});
      }
      await until(noteUp, 'the note');
      await settle();
      return { id: c.id, note: readNote(), asked, typed: { ...typed, total: typed.intake + typed.answers }, seconds: Math.round((Date.now() - started) / 1000) };
    };
  
    const results = [];
    const log = opts.log || ((s) => console.log(s));
    log(`Running ${CASES.length} cases on this page, one after another. Keep this tab in front; a hidden tab slows its timers.`);
    try {
      for (const [n, c] of CASES.entries()) {
        try {
          const out = await runCase(c);
          const fails = checkNote(c, out.note);
          results.push({ ...out, fails });
          log(`${n + 1} of ${CASES.length}: ${c.id}, ${fails.length ? 'FAIL' : 'pass'}, typed ${out.typed.total} words, ${new Set(out.asked.map((a) => a.round)).size} round(s), ${out.seconds}s`);
        } catch (err) {
          results.push({ id: c.id, fails: [`the run failed: ${err && err.message}`] });
          log(`${n + 1} of ${CASES.length}: ${c.id}, the run failed: ${err && err.message}`);
        }
      }
    } finally {
      window.fetch = realFetch;
    }
    return { at: new Date().toISOString(), page: location.pathname, results };
  }

  if (location.pathname !== "/notes/assess/") {
    throw new Error('Open ' + "/notes/assess/" + ' on tools.nooutco.me first, then paste this again.');
  }
  return benchInPage(CASES, checkNote).then((report) => {
    console.table(report.results.map((r) => ({ case: r.id, pass: !r.fails.length, typed: r.typed ? r.typed.total : '-', seconds: r.seconds || '-', fails: r.fails.join(' | ') || '-' })));
    window.benchReport = report;
    try {
      if (!copyNow) throw new Error('no console copy()');
      copyNow(JSON.stringify(report, null, 2));
      console.log('The results and the notes are on your clipboard.');
    } catch (e) {
      console.log('To put the results on your clipboard, type copy(benchReport) and press Enter.');
    }
    return report;
  });
})();
